<?php
require_once __DIR__ . '/../_lib/auth.php';
require_once __DIR__ . '/../_lib/helpers.php';
require_once __DIR__ . '/../_lib/data.php';
require_once __DIR__ . '/../_lib/cms.php';
auth_boot();require_login('content');if(!cms_module_aan('collectie')){header('Location: index.php');exit;}
function collectie_index($items,$id){foreach($items as $i=>$item){if(($item['id']??'')===$id)return $i;}return -1;}
$items=load_json('collectie.json',array());$actie=(string)($_GET['actie']??'lijst');$item=null;$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
if(!csrf_check()){$msg='Sessie verlopen, probeer het opnieuw.';}else{$post=(string)($_POST['actie']??'');$id=(string)($_POST['id']??'');$index=collectie_index($items,$id);
if($post==='verwijderen'&&$index>=0){array_splice($items,$index,1);save_json('collectie.json',array_values($items));header('Location: collectie.php?verwijderd=1');exit;}
if($post==='verplaatsen'&&$index>=0){$doel=(($_POST['richting']??'')==='omhoog')?$index-1:$index+1;if(isset($items[$doel])){$tmp=$items[$index];$items[$index]=$items[$doel];$items[$doel]=$tmp;}save_json('collectie.json',array_values($items));header('Location: collectie.php');exit;}
if($post==='opslaan'){$titel=trim((string)($_POST['titel']??''));$slug=strtolower(trim((string)($_POST['slug']??'')));$slug=trim((string)preg_replace('/[^a-z0-9]+/','-',$slug),'-');$categorie=trim((string)($_POST['categorie']??''));$samenvatting=trim((string)($_POST['samenvatting']??''));$tekst=trim(veld_html_opslaan((string)($_POST['tekst']??'')));$afbeelding=$index>=0?(string)($items[$index]['afbeelding']??''):'';
$up=verwerk_upload($_FILES['afbeelding_upload']??null);if(!$up['ok']){$msg=$up['fout'];$actie='form';}elseif($titel===''){$msg='Vul een titel in.';$actie='form';}else{if($up['pad']!=='')$afbeelding=$up['pad'];$nieuw=array('id'=>$id!==''?$id:cms_nieuwe_id('item'),'titel'=>$titel,'slug'=>$slug,'categorie'=>$categorie,'datum'=>trim((string)($_POST['datum']??'')),'samenvatting'=>$samenvatting,'tekst'=>$tekst,'afbeelding'=>$afbeelding,'actief'=>!empty($_POST['actief']));if($index>=0)$items[$index]=$nieuw;else$items[]=$nieuw;save_json('collectie.json',array_values($items));header('Location: collectie.php?opgeslagen=1');exit;}$item=array('id'=>$id,'titel'=>$titel,'slug'=>$slug,'categorie'=>$categorie,'datum'=>$_POST['datum']??'','samenvatting'=>$samenvatting,'tekst'=>$tekst,'afbeelding'=>$afbeelding,'actief'=>!empty($_POST['actief']));}
}}
if($actie==='nieuw'){$item=array('id'=>'','titel'=>'','slug'=>'','categorie'=>'','datum'=>date('Y-m-d'),'samenvatting'=>'','tekst'=>'','afbeelding'=>'','actief'=>true);$actie='form';}elseif($actie==='bewerk'){$index=collectie_index($items,(string)($_GET['id']??''));if($index<0){header('Location: collectie.php');exit;}$item=$items[$index];$actie='form';}
$pageTitle=CMS_COLLECTIE_LABEL;require __DIR__.'/_head.php';if(isset($_GET['opgeslagen']))echo '<p class="msg ok">'.e(ucfirst(CMS_COLLECTIE_ITEM_LABEL)).' opgeslagen.</p>';if(isset($_GET['verwijderd']))echo '<p class="msg ok">Item verwijderd.</p>';if($msg)echo '<p class="msg err">'.e($msg).'</p>';
if($actie==='form'):
?>
<div class="head-row"><h1><?= empty($item['id'])?ucfirst(CMS_COLLECTIE_ITEM_LABEL).' toevoegen':ucfirst(CMS_COLLECTIE_ITEM_LABEL).' bewerken' ?></h1><a class="btn ghost" href="collectie.php">Terug</a></div><form method="post" enctype="multipart/form-data" class="stack"><?= csrf_field() ?><input type="hidden" name="actie" value="opslaan"><input type="hidden" name="id" value="<?= e($item['id']??'') ?>"><label class="field"><span>Titel</span><input type="text" name="titel" value="<?= e($item['titel']??'') ?>" required></label><label class="field"><span>Slug</span><input type="text" name="slug" value="<?= e($item['slug']??'') ?>" placeholder="optioneel-uniek-adres"></label><label class="field"><span>Categorie</span><input type="text" name="categorie" value="<?= e($item['categorie']??'') ?>"></label><label class="field"><span>Datum</span><input type="date" name="datum" value="<?= e($item['datum']??'') ?>"></label><label class="field"><span>Samenvatting</span><textarea name="samenvatting" rows="3"><?= e($item['samenvatting']??'') ?></textarea></label><label class="field"><span>Volledige tekst</span><textarea name="tekst" rows="10"><?= e($item['tekst']??'') ?></textarea></label><label class="field"><span>Afbeelding</span><?php if(!empty($item['afbeelding'])):?><img class="preview" src="../<?= e($item['afbeelding']) ?>" alt=""><?php endif;?><input type="file" name="afbeelding_upload" accept="image/jpeg,image/png,image/gif,image/webp"><small class="hint">Laat leeg om de huidige afbeelding te behouden.</small></label><label class="field-check"><input type="checkbox" name="actief" value="1"<?= !empty($item['actief'])?' checked':'' ?>><span>Zichtbaar</span></label><div class="actions"><button class="btn">Opslaan</button><a class="btn ghost" href="collectie.php">Annuleren</a></div></form>
<?php else:?>
<div class="head-row"><h1><?= e(CMS_COLLECTIE_LABEL) ?></h1><a class="btn" href="?actie=nieuw">+ <?= e(ucfirst(CMS_COLLECTIE_ITEM_LABEL)) ?></a></div><p class="lead">Generieke module voor projecten, cases, diensten, teamleden of andere herhaalbare inhoud.</p><?php if(!$items):?><div class="info-blok"><p>Er zijn nog geen items.</p></div><?php else:?><table class="list"><thead><tr><th>Afbeelding</th><th>Titel</th><th>Categorie</th><th>Status</th><th class="right">Acties</th></tr></thead><tbody><?php foreach($items as $positie=>$rij):?><tr><td><?php if(!empty($rij['afbeelding'])):?><img class="review-thumb" src="../<?= e($rij['afbeelding']) ?>" alt=""><?php endif;?></td><td><strong><?= e($rij['titel']??'') ?></strong></td><td><?= e($rij['categorie']??'') ?></td><td><span class="badge <?= !empty($rij['actief'])?'ok':'err' ?>"><?= !empty($rij['actief'])?'zichtbaar':'verborgen' ?></span></td><td class="acties right"><form method="post"><?= csrf_field() ?><input type="hidden" name="actie" value="verplaatsen"><input type="hidden" name="id" value="<?= e($rij['id']) ?>"><button class="volgorde-knop" name="richting" value="omhoog"<?= $positie===0?' disabled':'' ?>>↑</button><button class="volgorde-knop" name="richting" value="omlaag"<?= $positie===count($items)-1?' disabled':'' ?>>↓</button></form><a href="?actie=bewerk&amp;id=<?= e(urlencode($rij['id'])) ?>">Bewerken</a><form method="post" data-confirm="Dit item verwijderen?"><?= csrf_field() ?><input type="hidden" name="actie" value="verwijderen"><input type="hidden" name="id" value="<?= e($rij['id']) ?>"><button class="link-del">Verwijderen</button></form></td></tr><?php endforeach;?></tbody></table><?php endif;endif;require __DIR__.'/_foot.php';?>

